"""Validation service for DQR4HL (DQRP5), generated by the DQVP pipeline.

In the Wetland.monitoringSite entity, the number of instances must be at least 5

The check is the DQVP constraint c-dqr4hl, compiled by the policy checker in
../policy_checker.ttl. It reads the data in place with DuckDB and returns the measured
value and whether DQR4HL is satisfied. service.json records where it comes from.

Run:  python validation_job.py [data folder]
      docker build -t dqr4hl . && docker run --rm -v <data folder>:/data dqr4hl /data
"""
import operator
import sys
from pathlib import Path

import duckdb

DATA = Path(__file__).resolve().parent / '../../../tools/dqvp/data/heleade'
LOADS = {'monitoring_site': "read_csv_auto('{data}/monitoring_site.csv')"}          # table -> load expression; {data} is the data folder
MEASURE = 'select min(r) from (select count(*) as r from "monitoring_site" group by "wetlandId")'
COMPARE, THRESHOLD = '>=', 5.0
OPS = {">=": operator.ge, "<=": operator.le, "==": operator.eq,
       ">": operator.gt, "<": operator.lt, "!=": operator.ne}


def run_validation(data_dir=DATA):
    """(measured value, satisfied); (None, None) when nothing can be measured."""
    con = duckdb.connect()
    for table, load in LOADS.items():
        con.execute(f'CREATE TABLE "{table}" AS SELECT * FROM '
                    + load.replace("{data}", Path(data_dir).as_posix()))
    value = con.execute(MEASURE).fetchone()[0]
    if value is None:
        return None, None
    value = round(float(value), 4)
    return value, OPS[COMPARE](value, THRESHOLD)


if __name__ == "__main__":
    value, ok = run_validation(sys.argv[1] if len(sys.argv) > 1 else DATA)
    print(f"DQR4HL  {value}  {'SATISFIED' if ok else 'VIOLATED'}")
